// Bounded source observation only. Every original false remains false.
static bool ownedNotFnTraceFalse(unsigned Line, const char *Function) {
  static unsigned Observations = 0;
  if (Observations++ < 16384)
    std::fprintf(stderr, "OWNED_NOT_FN_FALSE line=%u function=%s\n", Line, Function);
  return false;
}

