          Pending.pop_back();
          if (!D || !Graph.step()) return ownedNotFnTraceFalse(__LINE__, __func__);
          if (!Family.insert(D).second) continue;
          if (!approvedStandardSDKDeclaration(Graph.S, Graph.SM, D) ||
