            UtilityStringViewConstruction::PointerAndSize;
    const auto *CountSource = Complete ? Constructor->getParamDecl(1)->getTypeSourceInfo() : nullptr;
    const auto CountSpelling = CountSource
        ? CountSource->getTypeLoc().getAsAdjusted<TypedefTypeLoc>() : TypedefTypeLoc();
    Complete = Complete && CountSpelling && CountSpelling.getTypedefNameDecl() == Alias &&
        cstddefOrigin(S, SM, CountSpelling.getNameLoc(), "libcxx", "string_view") &&
        Context.hasSameType(Alias->getUnderlyingType(), Context.getSizeType()) &&
        Alias->getTypeSourceInfo() && family(Alias) && family(Owner) && family(Primary) &&
        family(Constructor);
    if (Complete) {
      for (unsigned I = 0; I != 2; ++I) {
        const auto *Operand = dyn_cast<OpaqueValueExpr>(E->getArg(I)->IgnoreParenImpCasts());
        auto Input = PairTraitQuery->getArg(I + 1)->getType();
        if (Input->isObjectType() || Input->isFunctionType())
          Input = Context.getRValueReferenceType(Input);
        if (!Operand || !Operands.count(Operand) || Operand->getSourceExpr() ||
            Constructor->getParamDecl(I)->hasDefaultArg() ||
            !Context.hasSameType(Operand->getType(), Input.getNonLValueExprType(Context)) ||
            Operand->getValueKind() != Expr::getValueKindForType(Input)) {
          Complete = false;
          break;
        }
      }
    }
    if (!Complete) Failed = true;
    return Complete;
  }
  bool record(const CXXRecordDecl *R) {
    if (!R || Failed) return ownedNotFnTraceFalse(__LINE__, __func__);
    if (Mode == UtilityTupleQueryMode::NotFnSignature && NotFnFactoryDefaults &&
        NotFnOwnedCallableRecord && NotFnConstructorDefaultParameter &&
        R->getCanonicalDecl() == NotFnFactoryDefaults->Selected.Storage.Tuple->getCanonicalDecl()) {
      // This is the actual forwarder's primary default, before its retained
      // constructor query. Empty P uses EBO and is not a generic tuple carrier.
      const auto &Storage = NotFnFactoryDefaults->Selected.Storage;
      const auto Owned = describeFunctionalNotFnOwnedStorage(S, SM, Storage.Record, Context);
      const auto *Instance = dyn_cast<ClassTemplateSpecializationDecl>(R);
      const auto *Definition = R->getDefinition();
      if (!Owned || Owned->Tuple != Storage.Tuple || !Instance || !Definition ||
          !family(R) || !family(Definition) || R->isInvalidDecl() ||
          Instance->getTemplateArgs().size() != 1 ||
          Instance->getTemplateArgs()[0].getKind() != TemplateArgument::Pack ||
          Instance->getTemplateArgs()[0].pack_size() != 1 ||
          Instance->getTemplateArgs()[0].pack_elements()[0].getKind() != TemplateArgument::Type ||
          !Context.hasSameType(Instance->getTemplateArgs()[0].pack_elements()[0].getAsType(), Storage.CallableType) ||
          Definition->getNumBases() || std::distance(Definition->field_begin(), Definition->field_end()) != 1 ||
          *Definition->field_begin() != Storage.TupleBase)
        return ownedNotFnTraceFalse(__LINE__, __func__);
      // A storage identity supplies metadata here, never a runtime operation
      // or an ordinary constructor, destructor or callback body certificate.
      return TraverseType(Storage.CallableType);
    }
    const auto *PairTrait = dyn_cast<ClassTemplateSpecializationDecl>(R);
    const auto *PairTraitPrimary = PairTrait ? PairTrait->getSpecializedTemplate() : nullptr;
    const auto *PairTraitCanonical = PairTraitPrimary ? PairTraitPrimary->getCanonicalDecl() : nullptr;
    if (Mode == UtilityTupleQueryMode::PairConstruction && PairTraitCanonical &&
        !isa<ClassTemplatePartialSpecializationDecl>(PairTrait) &&
        PairTraitCanonical->getIdentifier() &&
        PairTraitCanonical->getName() == "__is_implicitly_default_constructible" &&
        cstddefOrigin(S, SM, PairTraitCanonical->getLocation(), "libcxx",
                       "__type_traits/is_implicitly_default_constructible.h")) {
      // This exact SDK trait must close its original selection source before
      // either a bound metadata leaf or a generic record cache can admit it.
      const auto *Key = R->getCanonicalDecl();
      if (CompletedPairImplicitDefaults.count(Key)) return true;
      if (!ActivePairImplicitDefaults.insert(Key).second) {
        Failed = true;
        return ownedNotFnTraceFalse(__LINE__, __func__);
      }
      auto Restore = llvm::make_scope_exit([&] { ActivePairImplicitDefaults.erase(Key); });
      if (!family(R) || !pairImplicitDefaultSource(PairTrait)) {
        Failed = true;
        return ownedNotFnTraceFalse(__LINE__, __func__);
      }
      CompletedPairImplicitDefaults.insert(Key);
      return true;
    }
    if (Mode == UtilityTupleQueryMode::PairConstruction &&
        PairBorrowedStorageRecords.count(R->getCanonicalDecl())) {
      // The exact wrapper/base/zero-storage shape and SDK declaration family
      // were bound independently. Actual selected operations still close
      // their retained subobject choices and exception sources separately.
      return !R->isInvalidDecl() && family(R);
    }
    if (Mode == UtilityTupleQueryMode::PairConstruction &&
        PairInputRecords.count(R->getCanonicalDecl()) &&
        utilityUniquePtrRecord(S, SM, R, Context, false, false)) {
      if (!Records.insert(R).second) return !Failed;
      const bool Complete = ownerSource(R);
      if (!Complete) Failed = true;
      return Complete;
    }
    if (Mode == UtilityTupleQueryMode::PairConstruction &&
        PairInputRecords.count(R->getCanonicalDecl())) {
      // These exact identities came only from an independently admitted
      // Construction. Alias/TST source is still traversed by the outer RAV;
      // actual operations are separately completed by the ordinary checker.
      return !R->isInvalidDecl() &&
          (ownedPairInputRecord(R) || family(R));
    }
    if (Mode == UtilityTupleQueryMode::PairConstruction && pairOwner(R)) {
      if (!Records.insert(R).second) return true;
      const auto *Definition = R->getDefinition();
      if (!Definition || Definition->getNumBases() || !family(Definition)) return ownedNotFnTraceFalse(__LINE__, __func__);
      unsigned Fields = 0;
      for (const auto *Field : Definition->fields()) {
        if (++Fields > 2 || !family(Field) || Field->isBitField() ||
            Field->isMutable() || Field->hasAttrs() || Field->getAccess() != AS_public ||
            Field->getName() != (Fields == 1 ? "first" : "second") ||
            !TraverseType(Field->getType())) return ownedNotFnTraceFalse(__LINE__, __func__);
      }
      return Fields == 2;
    }
    if (Mode == UtilityTupleQueryMode::PairConstruction && pairHelperOwner(R))
      return true;
    if (Mode == UtilityTupleQueryMode::CatSignature && NotFnTupleTagStorage) {
      if (const auto *Owned = NotFnTupleTagStorage->CallableType->getAsCXXRecordDecl();
          Owned && R->getCanonicalDecl() == Owned->getCanonicalDecl())
        return describeFunctionalNotFnOwnedStorage(S, SM, NotFnTupleTagStorage->Record, Context).has_value();
      const auto *Target = NotFnTupleTagStorage->CallableType->isFunctionPointerType()
          ? NotFnTupleTagStorage->CallableType->getPointeeType()->getAs<FunctionProtoType>() : nullptr;
      const auto *Result = Target ? approvedFunctionalNotFnPointerResultRecord(
          S, SM, Target->getReturnType(), Context) : nullptr;
      // These constructor-tag slices name only the callback already retained
      // by this wrapper. Its ordinary result identity supplies metadata here;
      // it supplies no tuple_cat carrier, method, constructor or body grant.
      if (Result && R->getCanonicalDecl() == Result->getCanonicalDecl()) return true;
    }
    if (Mode == UtilityTupleQueryMode::CatSignature && NotFnTupleTagStorage &&
        R->getCanonicalDecl() == NotFnTupleTagStorage->Tuple->getCanonicalDecl()) {
      // This exact tuple was independently authenticated as the pointer
      // wrapper's storage. Consume its element in this metadata graph without
      // treating a function-pointer tuple as a generic tuple_cat carrier.
      const auto *Instance = dyn_cast<ClassTemplateSpecializationDecl>(R);
      const auto *Definition = R->getDefinition();
      if (!Instance || !Definition || !family(R) || !family(Definition) ||
          Instance->getTemplateArgs().size() != 1 ||
          Instance->getTemplateArgs()[0].getKind() != TemplateArgument::Pack ||
          Instance->getTemplateArgs()[0].pack_size() != 1) return ownedNotFnTraceFalse(__LINE__, __func__);
      const auto &Element = Instance->getTemplateArgs()[0].pack_elements()[0];
      return Element.getKind() == TemplateArgument::Type &&
          Context.hasSameType(Element.getAsType(), NotFnTupleTagStorage->CallableType) &&
          TraverseType(Element.getAsType());
    }
    if (Mode == UtilityTupleQueryMode::NotFnSignature && NotFnTupleLeafRecord &&
        R->getCanonicalDecl() == NotFnTupleLeafRecord) {
      // The actual is_same operand names the leaf already certified by this
      // wrapper's storage descriptor. Close its real field type, without
      // turning function-pointer tuples into general metadata carriers.
      const auto *Definition = R->getDefinition();
      if (Definition && NotFnTupleLeafEmptyBase) {
        if (!NotFnOwnedCallableRecord || NotFnTupleLeafValue || !family(R) || !family(Definition) ||
            !Definition->field_empty() || Definition->getNumBases() != 1) return ownedNotFnTraceFalse(__LINE__, __func__);
        const auto &Base = *Definition->bases_begin();
        const auto *Owner = Base.getType()->getAsCXXRecordDecl();
        return Owner && !Base.isVirtual() && Base.getAccessSpecifier() == AS_private &&
            Owner->getCanonicalDecl() == NotFnTupleLeafEmptyBase &&
            NotFnTupleLeafEmptyBase == NotFnOwnedCallableRecord && TraverseType(Base.getType());
      }
      if (!Definition || !NotFnTupleLeafValue || !family(R) || !family(Definition) ||
          Definition->getNumBases() || Definition->isUnion() || Definition->isDynamicClass() ||
          std::distance(Definition->field_begin(), Definition->field_end()) != 1 ||
          *Definition->field_begin() != NotFnTupleLeafValue || !family(NotFnTupleLeafValue) ||
          !Context.hasSameType(NotFnTupleLeafValue->getType(), NotFnCallableType)) return ownedNotFnTraceFalse(__LINE__, __func__);
      return TraverseType(NotFnTupleLeafValue->getType());
    }
    if (carrier(Context.getRecordType(R))) {
      if (Mode != UtilityTupleQueryMode::CatSignature) return true;
      if (!family(R)) return ownedNotFnTraceFalse(__LINE__, __func__);
      // The layout descriptor is structural evidence only. Close each actual
      // tuple-like element in the SDK signature graph as well.
      if (const auto Storage = approvedUtilityTupleCatQueryLayout(
              S, SM, Context.getRecordType(R), Context)) {
        if (!Records.insert(R).second) return true;
        if (Storage->ArrayElements)
          return TraverseType(Storage->ArrayElementType);
        for (unsigned I = 0; I < Storage->size(); ++I)
          if (!TraverseType(Storage->elementType(I))) return ownedNotFnTraceFalse(__LINE__, __func__);
        return true;
      }
      if (approvedMemoryTemplateMetadata(S, SM, R) == MemoryTemplateMetadata::UniquePtr)
        return ownerSource(R);
      // String and view descriptors authenticate their exact traits/storage.
      return approvedUtilityStringRecord(S, SM, R, Context).has_value() ||
             approvedUtilityStringViewRecord(S, SM, R, Context).has_value();
    }
    if (Mode == UtilityTupleQueryMode::NotFnSignature && NotFnOperationRecord &&
        R->getCanonicalDecl() == NotFnOperationRecord) {
      // This is the operation identity in the independently authenticated
      // pointer wrapper, consumed as a constraint type only. Its actual call,
      // forwarding, negation and exception bodies still close separately.
      const auto *Definition = R->getDefinition();
      return Definition && family(R) && family(Definition) &&
          Definition->getCanonicalDecl() == NotFnOperationRecord &&
          !Definition->isUnion() && !Definition->isDynamicClass() &&
          !Definition->getNumBases() && Definition->field_empty() &&
          Definition->hasTrivialDefaultConstructor() &&
          Definition->hasTrivialDestructor();
    }
    if (Mode == UtilityTupleQueryMode::NotFnSignature && NotFnInvocation &&
        NotFnResultComparisonRecord &&
        R->getCanonicalDecl() == NotFnResultComparisonRecord) {
      // Only the actual second _IsNotSame operand consumes this already
      // authenticated, deleted SDK sentinel. No value, call, construction or
      // lifetime source is registered by a metadata type comparison.
      const auto *Definition = R->getDefinition();
      const bool Complete = Definition && family(R) && family(Definition) &&
          !Definition->isUnion() && !Definition->isDynamicClass() &&
          !Definition->getNumBases() && Definition->field_empty();
      if (!Complete) Failed = true;
      return Complete;
    }
    if (!family(R)) return ownedNotFnTraceFalse(__LINE__, __func__);
    if (!Records.insert(R).second) return true;
    const auto *Instance = dyn_cast<ClassTemplateSpecializationDecl>(R);
    if (Instance && Instance->getIdentifier() && Instance->getName() == "__make_tuple_types" &&
        !fullSliceDefaults(Instance)) return ownedNotFnTraceFalse(__LINE__, __func__);
    if (!Instance) return ownedNotFnTraceFalse(__LINE__, __func__);
    for (const auto &Argument : Instance->getTemplateArgs().asArray())
      if (!TraverseTemplateArgument(Argument)) return ownedNotFnTraceFalse(__LINE__, __func__);
    const auto *Definition = R->getDefinition();
    if (!Definition) return true; // Unconsumed metadata remains lazy.
    if (!family(Definition) || Definition->isUnion() ||
        Definition->isDynamicClass() || Definition->getNumVBases())
      return ownedNotFnTraceFalse(__LINE__, __func__);
    for (const auto &Base : Definition->bases()) {
      const auto *SavedOwner = NotFnConstraintBaseOwner;
      const auto *SavedBase = NotFnConstraintBase;
      if (Mode == UtilityTupleQueryMode::NotFnSignature) {
        NotFnConstraintBaseOwner = Definition;
        NotFnConstraintBase = &Base;
      }
      auto Restore = llvm::make_scope_exit([&] {
        NotFnConstraintBaseOwner = SavedOwner;
        NotFnConstraintBase = SavedBase;
      });
      if (Base.isVirtual() || !Base.getTypeSourceInfo() ||
          !TraverseTypeLoc(Base.getTypeSourceInfo()->getTypeLoc())) return ownedNotFnTraceFalse(__LINE__, __func__);
    }
    // Only referenced value/alias members are consumed below. Never walk
    // metadata's unselected constructors or manufacture a definition.
    return Definition->field_empty();
  }
  bool value(const ValueDecl *D, const DeclRefExpr *Reference = nullptr) {
    if (!family(D) || !TraverseType(D->getType())) return ownedNotFnTraceFalse(__LINE__, __func__);
    if (const auto *Parameter = dyn_cast<NonTypeTemplateParmDecl>(D)) {
      if (Mode == UtilityTupleQueryMode::CatSignature)
        if (const auto Found = CatDefinitionParameters.find(Parameter);
            Found != CatDefinitionParameters.end()) {
          const auto *Parameters = Found->second;
          // This exact symbolic declaration belongs to an authenticated
          // written definition. Reading its identity consumes no instance
          // body, canonical dependent arguments, or default expression.
          return Parameter->getIndex() < Parameters->size() &&
              Parameters->getParam(Parameter->getIndex()) == Parameter;
        }
      const auto Found = DefinitionParameters.find(Parameter);
      if (Found != DefinitionParameters.end()) {
        const auto *Primary = Found->second;
        const auto *Parameters = Primary->getTemplateParameters();
        return family(Primary) && Parameter->getDeclContext() == Primary->getTemplatedDecl() &&
            Parameter->getIndex() < Parameters->size() &&
            Parameters->getParam(Parameter->getIndex()) == Parameter;
      }
    }
    if (const auto *R = dyn_cast<CXXRecordDecl>(D->getDeclContext()))
      if (!record(R)) return ownedNotFnTraceFalse(__LINE__, __func__);
    if (const auto *V = dyn_cast<VarDecl>(D)) {
      if (!V->isStaticDataMember()) {
        // Only the bound not_fn proof can consume this exact retained use
        // and its selected initializer. No namespace constant joins the
        // ordinary SDK metadata permissions or any other graph mode.
        return Mode == UtilityTupleQueryMode::NotFnSignature && Reference &&
            Reference->getDecl() == V && NotFnConstraintVariableSource &&
            NotFnConstraintVariableSource(Reference);
      }
      if (!V->isConstexpr())
        return Mode == UtilityTupleQueryMode::NotFnSignature && Reference &&
            Reference->getDecl() == V && NotFnConstraintVariableSource &&
            NotFnConstraintVariableSource(Reference);
      const VarDecl *Holder = nullptr;
      const auto *Initializer = V->getAnyInitializer(Holder);
      return Initializer && Holder && family(Holder) &&
             Holder->getCanonicalDecl() == V->getCanonicalDecl() &&
             TraverseStmt(const_cast<Expr *>(Initializer));
    }
    return isa<NonTypeTemplateParmDecl>(D);
  }

public:
  UtilityTupleQueryGraph(const State &S, const SourceManager &SM,
                        const ASTContext &Context,
                        const std::map<const CXXMethodDecl *, SpecialMemberSource> &Members,
                        const std::map<const TypeTraitExpr *, OperationTraitSource> &Traits,
                        UtilityTupleQueryMode Mode = UtilityTupleQueryMode::Construction)
      : S(S), SM(SM), Context(Context), SpecialMembers(Members), OperationTraits(Traits), Mode(Mode) {}
  bool bindNotFnTupleTagSlices(const FunctionalNotFnFactorySource &Factory,
      llvm::ArrayRef<FunctionalNotFnTupleTagSource> Tags, bool Owned = false) {
    if (Mode != UtilityTupleQueryMode::CatSignature || !NotFnTupleTagSlices.empty() ||
        NotFnTupleTagStorage || Tags.size() != 4 ||
        Factory.SelectedConstructions.size() != 4) return ownedNotFnTraceFalse(__LINE__, __func__);
    const auto Pointer = Owned ? describeFunctionalNotFnOwnedStorage(S, SM, Factory.Storage.Record, Context)
        : approvedFunctionalNotFnPointerStorage(S, SM, Factory.Storage.Record, Context);
    const auto *TupleInstance = Pointer ? dyn_cast<ClassTemplateSpecializationDecl>(Pointer->Tuple) : nullptr;
    const auto *Construction = Factory.SelectedConstructions[1];
    const auto *Constructor = Construction ? Construction->getConstructor() : nullptr;
    const auto *Primary = Constructor ? Constructor->getPrimaryTemplate() : nullptr;
    const auto *Arguments = Constructor ? Constructor->getTemplateSpecializationArgs() : nullptr;
    if (!Pointer || !TupleInstance || Pointer->Tuple != Factory.Storage.Tuple || !Constructor || !Primary ||
        !Arguments || Arguments->size() != 2 || Arguments->get(0).getKind() != TemplateArgument::Pack ||
        Arguments->get(0).pack_size() != 1 || Construction->getNumArgs() != 1 ||
        Constructor->getParent()->getCanonicalDecl() != Pointer->Tuple->getCanonicalDecl() ||
        !family(Constructor)) return ownedNotFnTraceFalse(__LINE__, __func__);
    std::set<const NamedDecl *> InputPacks, StoredPacks;
    std::set<const FunctionTemplateDecl *> Seen;
    for (const auto *Current = Primary; Current;) {
      if (!step() || !Seen.insert(Current).second || !family(Current) ||
          !Current->getTemplateParameters()->size()) return ownedNotFnTraceFalse(__LINE__, __func__);
      const auto *Pack = dyn_cast<TemplateTypeParmDecl>(Current->getTemplateParameters()->getParam(0));
      if (!Pack || !Pack->isParameterPack() || !family(Pack)) return ownedNotFnTraceFalse(__LINE__, __func__);
      InputPacks.insert(Pack);
      Current = Current->getInstantiatedFromMemberTemplate();
    }
    for (const auto *Template : TupleInstance->getSpecializedTemplate()->redecls()) {
      if (!step() || !family(Template) || Template->getTemplateParameters()->size() != 1)
        return ownedNotFnTraceFalse(__LINE__, __func__);
      const auto *Pack = dyn_cast<TemplateTypeParmDecl>(Template->getTemplateParameters()->getParam(0));
      if (!Pack || !Pack->isParameterPack() || !family(Pack)) return ownedNotFnTraceFalse(__LINE__, __func__);
      StoredPacks.insert(Pack);
    }
    for (unsigned I : {1U, 3U}) {
      const auto &Tag = Tags[I];
      if (!Tag.Written || !Tag.Construction ||
          Tag.Construction->getConstructor()->getParent()->getCanonicalDecl() !=
              Tag.Record->getCanonicalDecl()) return ownedNotFnTraceFalse(__LINE__, __func__);
      const auto Written = Tag.Written->getTypeLoc().getAs<ElaboratedTypeLoc>();
      const auto Qualifier = Written.isNull() ? NestedNameSpecifierLoc() : Written.getQualifierLoc();
      const auto Location = Qualifier ? Qualifier.getTypeLoc().getAs<TemplateSpecializationTypeLoc>()
                                      : TemplateSpecializationTypeLoc();
      const auto *Use = Location.isNull() ? nullptr : Location.getTypePtr();
      const auto *Template = Use ? Use->getTemplateName().getAsTemplateDecl() : nullptr;
      const auto *Instance = Use ? dyn_cast_or_null<ClassTemplateSpecializationDecl>(Use->getAsCXXRecordDecl()) : nullptr;
      const auto Count = I == 1 ? 2U : 3U;
      if (!Use || !Template || !Instance || !Template->getIdentifier() ||
          Template->getName() != "__make_tuple_types" || !family(Template) ||
          Location.getNumArgs() != Count || Use->template_arguments().size() != Count ||
          Location.getArgLoc(0).getArgument().getKind() != TemplateArgument::Type ||
          !Context.hasSameType(Location.getArgLoc(0).getArgument().getAsType(),
                               Context.getRecordType(Pointer->Tuple)) ||
          !cstddefOrigin(S, SM, Location.getTemplateNameLoc(), "libcxx", "tuple")) return ownedNotFnTraceFalse(__LINE__, __func__);
      for (unsigned J = 1; J != Count; ++J) {
        const auto Argument = Location.getArgLoc(J);
        const auto Kind = Argument.getArgument().getKind();
        const Expr *Expression = Kind == TemplateArgument::Expression ? Argument.getSourceExpression()
            : Kind == TemplateArgument::Integral ? Argument.getSourceIntegralExpression() : nullptr;
        const auto *Pack = Expression ? dyn_cast<SizeOfPackExpr>(Expression->IgnoreParenImpCasts()) : nullptr;
        const auto &Expected = I == 1 || J == 2 ? InputPacks : StoredPacks;
        if (!Pack || Pack->isValueDependent() || Pack->getPackLength() != 1 ||
            !Expected.count(Pack->getPack()) || !family(Pack->getPack()) ||
            !cstddefOrigin(S, SM, Pack->getExprLoc(), "libcxx", "tuple")) return ownedNotFnTraceFalse(__LINE__, __func__);
      }
      // Both actual ranges end at this independently described one-element
      // storage. The fourth tag's explicit start is one, so its slice is empty.
      if (!NotFnTupleTagSlices.emplace(Instance->getCanonicalDecl(),
              std::make_pair(Use, I == 1 ? 0U : 1U)).second) return ownedNotFnTraceFalse(__LINE__, __func__);
    }
    NotFnTupleTagStorage = *Pointer;
    return true;
  }
  bool bindNotFnOwnedInputAliases(
      const FunctionalNotFnFactoryTemplateSource &Factory,
      const std::function<bool(const TypedefNameDecl *)> &SourceAlias) {
    if (Mode != UtilityTupleQueryMode::NotFnSignature ||
        NotFnFactoryDefaults != &Factory || NotFnCallableType.isNull() ||
        !NotFnOwnedInputAliases.empty() || !Factory.Use.Canonical ||
        !Factory.Use.Sugared || Factory.Use.Canonical->size() != 2 ||
        Factory.Use.Sugared->size() != 2 ||
        Factory.Use.Canonical->get(0).getKind() != TemplateArgument::Type ||
        Factory.Use.Sugared->get(0).getKind() != TemplateArgument::Type ||
        !Context.hasSameType(Factory.Use.Canonical->get(0).getAsType(),
                             Factory.Use.Sugared->get(0).getAsType())) return ownedNotFnTraceFalse(__LINE__, __func__);
    auto Input = Factory.Use.Sugared->get(0).getAsType().getNonReferenceType();
    std::map<const TypedefNameDecl *, const TypeSourceInfo *> Pending;
    for (unsigned I = 0; ; ++I) {
      if (I >= 64 || !step() || Input.isNull()) return ownedNotFnTraceFalse(__LINE__, __func__);
      if (const auto *Elaborated = dyn_cast<ElaboratedType>(Input.getTypePtr())) {
        Input = Elaborated->getNamedType();
        continue;
      }
      const auto *Type = dyn_cast<TypedefType>(Input.getTypePtr());
      if (!Type) break;
      const auto *Alias = Type->getDecl();
      const auto *Info = Alias ? Alias->getTypeSourceInfo() : nullptr;
      const auto *Named = dyn_cast_or_null<TypeAliasDecl>(Alias);
      if (!Alias || !Info || Alias->isInvalidDecl() || Alias->hasAttrs() ||
          !Alias->getDeclContext()->isFileContext() ||
          Alias->getLocation().isMacroID() || !S.owns(SM, Alias->getLocation()) ||
          approvedStandardSDKDeclaration(S, SM, Alias) ||
          (Named && Named->getDescribedAliasTemplate()) ||
          (!Alias->getUnderlyingType()->isFunctionPointerType() && !NotFnOwnedCallableRecord) ||
          !Context.hasSameType(Alias->getUnderlyingType(), NotFnCallableType) ||
          !Pending.emplace(Alias, Info).second) return ownedNotFnTraceFalse(__LINE__, __func__);
      // Complete the actual alias TSI, callback signature and owned spelling
      // before exposing this one raw typedef identity to the metadata graph.
      if (!SourceAlias || !SourceAlias(Alias)) return ownedNotFnTraceFalse(__LINE__, __func__);
      Input = Alias->getUnderlyingType();
    }
    NotFnOwnedInputAliases = std::move(Pending);
    return true;
  }
  bool bindNotFnOperation(const FunctionalNotFnStorage &Storage,
      std::set<const CXXMethodDecl *> *OwnedQuerySources = nullptr) {
    if (Mode != UtilityTupleQueryMode::NotFnSignature || NotFnOperationRecord)
      return ownedNotFnTraceFalse(__LINE__, __func__);
    const auto Pointer = OwnedQuerySources
        ? describeFunctionalNotFnOwnedStorage(S, SM, Storage.Record, Context)
        : approvedFunctionalNotFnPointerStorage(S, SM, Storage.Record, Context);
    if (!Pointer || Pointer->Operation != Storage.Operation ||
        !Context.hasSameType(Pointer->CallableType, Storage.CallableType) || !Pointer->TupleLeaf)
      return ownedNotFnTraceFalse(__LINE__, __func__);
    if (Pointer->Callable.EmptyBase) {
      const auto *Leaf = Pointer->TupleLeaf->getDefinition();
      if (!OwnedQuerySources || !Leaf || !Leaf->field_empty() || Leaf->getNumBases() != 1 ||
          Pointer->Callable.Field || !Pointer->Callable.EmptyBase->isEmpty() ||
          Leaf->bases_begin()->getType()->getAsCXXRecordDecl()->getCanonicalDecl() !=
              Pointer->Callable.EmptyBase->getCanonicalDecl()) return ownedNotFnTraceFalse(__LINE__, __func__);
      NotFnTupleLeafEmptyBase = Pointer->Callable.EmptyBase->getCanonicalDecl();
    } else if (!Pointer->Callable.Field || Pointer->Callable.Field->getParent()->getCanonicalDecl() !=
                   Pointer->TupleLeaf->getCanonicalDecl()) return ownedNotFnTraceFalse(__LINE__, __func__);
    NotFnOperationRecord = Pointer->Operation->getCanonicalDecl();
    NotFnTupleLeafRecord = Pointer->TupleLeaf->getCanonicalDecl();
    NotFnTupleLeafValue = Pointer->Callable.Field;
    NotFnCallableType = Pointer->CallableType;
    if (OwnedQuerySources) {
      NotFnOwnedCallableRecord = Pointer->CallableType->getAsCXXRecordDecl()->getCanonicalDecl();
      NotFnOwnedQuerySources = OwnedQuerySources;
    } else if (const auto *Result = approvedFunctionalNotFnPointerResultRecord(S, SM,
            NotFnCallableType->getPointeeType()->getAs<FunctionProtoType>()->getReturnType(), Context))
      NotFnCallbackResultRecord = Result->getCanonicalDecl();
    return true;
  }
  bool withNotFnInvocation(const FunctionalNotFnCallSource &Call,
                           std::function<bool()> Proof) {
    if (Mode != UtilityTupleQueryMode::NotFnSignature || NotFnInvocation ||
        !NotFnSignatureDeclvals.empty() || !NotFnTryResultUses.empty() ||
        !NotFnOperationTryResultUses.empty() ||
        NotFnPublicInvoke || NotFnPublicOperation || NotFnOperationQuery ||
        NotFnOperationInvokeFunction || !NotFnOperationInvokeUses.empty() ||
        NotFnOperationInvokeSignatureActive || !NotFnPublicInvokeUses.empty() ||
        !NotFnPublicForwards.empty() || !NotFnPublicParameters.empty() || !NotFnNegationUses.empty() ||
        NotFnOwnedInvokeMethod || !NotFnOwnedInvokeQueries.empty() ||
        !NotFnQueryBindings.empty() ||
        !NotFnResultSentinels.empty() || NotFnResultComparisonRecord ||
        NotFnResultWrittenArgument || NotFnResultWrittenSentinel ||
