        !Rest->isParameterPack() || Rest->hasDefaultArgument() ||
        !Check.family(First, {"__type_traits/invoke.h"}) ||
        !Check.family(Rest, {"__type_traits/invoke.h"})) return ownedNotFnTraceFalse(__LINE__, __func__);
    for (const auto *Redeclaration : Variable->redecls())
      if (!Check.family(Redeclaration, {"__type_traits/invoke.h"})) return ownedNotFnTraceFalse(__LINE__, __func__);
    const auto *Method = Call.Method;
    const auto *CallArguments = Method ? Method->getTemplateSpecializationArgs() : nullptr;
    if (!Method || !CallArguments || CallArguments->size() != 2 ||
        CallArguments->get(0).getKind() != TemplateArgument::Pack ||
        CallArguments->get(0).pack_size() != Method->getNumParams() ||
        Method->getNumParams() > 64 ||
        !Check.family(Method, {"__functional/perfect_forward.h"})) return ownedNotFnTraceFalse(__LINE__, __func__);
    const auto &Arguments = Variable->getTemplateArgs();
    if (Arguments.size() != 2 || Arguments[0].getKind() != TemplateArgument::Type ||
        Arguments[1].getKind() != TemplateArgument::Pack ||
        Arguments[1].pack_size() != Method->getNumParams() + (DirectCallable ? 0 : 1)) return ownedNotFnTraceFalse(__LINE__, __func__);
    auto Bound = Method->isConst() ? Context.getConstType(Call.Storage.CallableType)
                                 : Call.Storage.CallableType;
    if (Method->getRefQualifier() == RQ_LValue)
      Bound = Context.getLValueReferenceType(Bound);
    else if (Method->getRefQualifier() != RQ_RValue) return ownedNotFnTraceFalse(__LINE__, __func__);
    const auto Pack = Arguments[1].pack_elements();
    const unsigned Offset = DirectCallable ? 0 : 1;
    if (!Context.hasSameType(Arguments[0].getAsType(), DirectCallable
            ? Bound : Context.getRecordType(Call.Storage.Operation))) return ownedNotFnTraceFalse(__LINE__, __func__);
    if (!DirectCallable && (Pack[0].getKind() != TemplateArgument::Type ||
        !Context.hasSameType(Pack[0].getAsType(), Bound))) return ownedNotFnTraceFalse(__LINE__, __func__);
    const auto Selected = CallArguments->get(0).pack_elements();
    for (unsigned I = 0; I < Selected.size(); ++I)
      if (Selected[I].getKind() != TemplateArgument::Type ||
          Pack[I + Offset].getKind() != TemplateArgument::Type ||
          !Context.hasSameType(Pack[I + Offset].getAsType(), Selected[I].getAsType())) return ownedNotFnTraceFalse(__LINE__, __func__);
    if (!Internal) {
      bool Found = false;
      for (const auto *Source : Sources) {
        if (!Source || Source->Kind != TemplateSourceKind::VariableUse ||
            Source->Declaration != Variable || Source->Location != Reference->getExprLoc()) continue;
        if (!Source->FunctionalNotFnConstraint || Source->Template != Primary ||
            Source->Type || Source->Underlying || !arguments(*Source) ||
            !Source->Defaults.empty() || !Source->ParameterTypes.empty() ||
            Source->Canonical->size() != Arguments.size()) return ownedNotFnTraceFalse(__LINE__, __func__);
        for (unsigned I = 0; I < Arguments.size(); ++I)
          if (!Source->Canonical->get(I).structurallyEquals(Arguments[I])) return ownedNotFnTraceFalse(__LINE__, __func__);
        Found = true;
      }
      if (!Found || !Check.location(Reference->getExprLoc(),
                                    {"__functional/perfect_forward.h"})) return ownedNotFnTraceFalse(__LINE__, __func__);
      // Only the actual child of this authenticated outer initializer may
      // consume the SDK's non-constexpr inline const implementation variable.
      // Its identity, arguments and selected primary close again on reentry.
      const auto *Load = dyn_cast<ImplicitCastExpr>(Variable->getInit());
      const auto *Child = Load && Load->getCastKind() == CK_LValueToRValue
          ? dyn_cast<DeclRefExpr>(Load->getSubExpr()) : nullptr;
      if (!Child || !Check.location(Child->getExprLoc(), {"__type_traits/invoke.h"}) ||
          !InvocableVariableChildren.insert(Child).second) return ownedNotFnTraceFalse(__LINE__, __func__);
      auto Restore = llvm::make_scope_exit([&] { InvocableVariableChildren.erase(Child); });
      return Graph.TraverseStmt(const_cast<Expr *>(Variable->getInit()));
    }
    const auto *Load = dyn_cast<ImplicitCastExpr>(Variable->getInit());
    const auto *Value = Load && Load->getCastKind() == CK_LValueToRValue
        ? dyn_cast<DeclRefExpr>(Load->getSubExpr()) : nullptr;
    const auto *Member = Value ? dyn_cast<VarDecl>(Value->getDecl()) : nullptr;
    const auto *Owner = Member
        ? dyn_cast<ClassTemplateSpecializationDecl>(Member->getDeclContext()) : nullptr;
    const auto *OwnerPrimary = Owner ? Owner->getSpecializedTemplate() : nullptr;
    if (!Owner || !OwnerPrimary || !OwnerPrimary->getIdentifier() ||
        OwnerPrimary->getName() != "__invokable_r" || Member->getName() != "value" ||
        !Member->isStaticDataMember() ||
        Owner->getSpecializationKind() != TSK_ImplicitInstantiation ||
        Owner->getSpecializedTemplateOrPartial().dyn_cast<ClassTemplateDecl *>() != OwnerPrimary ||
        !Check.family(Owner, {"__type_traits/invoke.h"}) ||
        !Check.family(Member, {"__type_traits/invoke.h"}) ||
        Owner->getTemplateArgs().size() != 3 ||
        Owner->getTemplateArgs()[0].getKind() != TemplateArgument::Type ||
        !Owner->getTemplateArgs()[0].getAsType()->isVoidType() ||
        Owner->getTemplateArgs()[1].getKind() != TemplateArgument::Type ||
        !Context.hasSameType(Owner->getTemplateArgs()[1].getAsType(), Arguments[0].getAsType()) ||
        Owner->getTemplateArgs()[2].getKind() != TemplateArgument::Pack ||
        Owner->getTemplateArgs()[2].pack_size() != Pack.size()) return ownedNotFnTraceFalse(__LINE__, __func__);
    const auto ActualPack = Owner->getTemplateArgs()[2].pack_elements();
    for (unsigned I = 0; I < Pack.size(); ++I)
      if (ActualPack[I].getKind() != TemplateArgument::Type ||
          !Context.hasSameType(ActualPack[I].getAsType(), Pack[I].getAsType())) return ownedNotFnTraceFalse(__LINE__, __func__);
    // The actual __is_invocable alias keeps its written void return argument.
    // Closing that TypeLoc is independent of its canonical void value.
    return Graph.withNotFnOperationQuery(DirectCallable ? nullptr : Reference, [&] {
      const auto Qualifier = Value->getQualifierLoc();
      if (!Qualifier || !Graph.TraverseTypeLoc(Qualifier.getTypeLoc()) ||
          !InvocableValueReferences.emplace(Value, Owner).second) return ownedNotFnTraceFalse(__LINE__, __func__);
      auto Restore = llvm::make_scope_exit([&] { InvocableValueReferences.erase(Value); });
      return Graph.TraverseStmt(const_cast<Expr *>(Variable->getInit()));
    });
  }
  bool decay(TemplateSpecializationTypeLoc Root, QualType Input, QualType Output) {
    const auto *Source = typeUse(Root);
    const auto *Alias = Source ? dyn_cast<TypeAliasTemplateDecl>(Source->Template) : nullptr;
    if (!Source || !Alias || Alias->getName() != "decay_t" ||
        !Source->Defaults.empty() || !Source->ParameterTypes.empty() ||
        !Check.family(Alias, {"__type_traits/decay.h"}) || Root.getNumArgs() != 1 ||
        Root.getArgLoc(0).getArgument().getKind() != TemplateArgument::Type ||
        !Context.hasSameType(Root.getArgLoc(0).getArgument().getAsType(), Input) ||
        !Context.hasSameType(Source->Underlying->getType(), Output)) return ownedNotFnTraceFalse(__LINE__, __func__);
    const auto *Inner = specialization(Source->Underlying->getType());
    const auto *Template = Inner ? dyn_cast_or_null<TypeAliasTemplateDecl>(
        Inner->getTemplateName().getAsTemplateDecl()) : nullptr;
    const auto *Transform = Inner && Inner->isTypeAlias()
        ? dyn_cast<UnaryTransformType>(Inner->getAliasedType().getTypePtr()) : nullptr;
    if (!Template || Template->getName() != "__decay_t" ||
        !Check.family(Template, {"__type_traits/decay.h"}) || !Transform ||
        Transform->getUTTKind() != UnaryTransformType::Decay ||
        !Context.hasSameType(Transform->getBaseType(), Input) ||
        !Context.hasSameType(Transform->getUnderlyingType(), Output)) return ownedNotFnTraceFalse(__LINE__, __func__);
    return Graph.TraverseTypeLoc(Source->Underlying->getTypeLoc()) &&
           Graph.TraverseTypeLoc(Alias->getTemplatedDecl()->getTypeSourceInfo()->getTypeLoc());
  }

public:
  NotFnPointerSourceProof(const State &S, const SourceManager &SM,
      const ASTContext &Context, llvm::ArrayRef<const TemplateUseSource *> Sources,
      llvm::ArrayRef<const SelectedTemplateCallSource *> Selections,
      const std::map<const CXXMethodDecl *, SpecialMemberSource> &Members,
      const std::map<const TypeTraitExpr *, OperationTraitSource> &Traits,
      std::function<bool(const TypedefNameDecl *)> SourceAlias = {})
      : S(S), SM(SM), Context(Context), Check(S, SM, Context),
        SpecialMembers(Members), OperationTraits(Traits),
        Graph(S, SM, Context, Members, Traits, UtilityTupleQueryMode::NotFnSignature),
        Sources(Sources), Selections(Selections), OwnedInputAliasSource(std::move(SourceAlias)) {}
  NotFnPointerSourceProof(const NotFnPointerSourceProof &) = delete;
  NotFnPointerSourceProof &operator=(const NotFnPointerSourceProof &) = delete;

  bool factory(const FunctionalNotFnFactoryTemplateSource &Factory,
      std::set<const CXXMethodDecl *> *OwnedQuerySources = nullptr) {
    const auto Pointer = OwnedQuerySources
        ? describeFunctionalNotFnOwnedStorage(S, SM, Factory.Selected.Storage.Record, Context)
        : approvedFunctionalNotFnPointerStorage(S, SM, Factory.Selected.Storage.Record, Context);
    if (!Pointer || (OwnedQuerySources ? !Factory.Selected.CallableConstruction
                                     : bool(Factory.Selected.CallableConstruction)) ||
        !Graph.bindNotFnFactoryDefaults(Factory) ||
        !Graph.bindNotFnOperation(Factory.Selected.Storage, OwnedQuerySources)) return ownedNotFnTraceFalse(__LINE__, __func__);
    const auto Input = Factory.Use.Canonical->get(0).getAsType();
    const auto Callable = Pointer->CallableType;
    // This first slice stores only an actual function pointer, with no
    // user-defined construction, conversion, negation or destruction.
    const auto InputValue = Input.getNonReferenceType();
    const auto Decayed = InputValue->isFunctionType()
        ? Context.getPointerType(InputValue) : InputValue.getUnqualifiedType();
    if ((OwnedQuerySources ? !InputValue->isRecordType()
                          : (!InputValue->isFunctionPointerType() && !InputValue->isFunctionType())) ||
        !Context.hasSameType(Decayed, Callable) ||
        !Graph.bindNotFnOwnedInputAliases(Factory, OwnedInputAliasSource)) return ownedNotFnTraceFalse(__LINE__, __func__);
    if (!Graph.bindNotFnConstraintVariables(
            [this, Callable, Input, Storage = *Pointer](const DeclRefExpr *Reference) {
              if (!Reference) return ownedNotFnTraceFalse(__LINE__, __func__);
              if (!Check.location(Reference->getExprLoc(), {"__functional/not_fn.h"}))
                return constructorVariableUse(Reference, Storage);
              const auto *Variable = dyn_cast<VarTemplateSpecializationDecl>(Reference->getDecl());
              const auto *Primary = Variable ? Variable->getSpecializedTemplate() : nullptr;
              if (!Primary || !Primary->getIdentifier() ||
                  (Primary->getName() != "is_constructible_v" &&
                   Primary->getName() != "is_move_constructible_v")) return ownedNotFnTraceFalse(__LINE__, __func__);
              // Reuse the complete packet/argument/redeclaration/initializer
              // proof below; neither the variable's name nor its folded bool
              // can stand in for an actual retained constraint source.
              return variableUse(Reference, Primary->getName(), Callable, Input);
            })) return ownedNotFnTraceFalse(__LINE__, __func__);
    const auto Primary = specialization(Factory.PrimaryDefault);
    const auto *PrimaryCondition = Primary.isNull() ? nullptr
        : Primary.getArgLoc(0).getArgument().getAsExpr();
    const auto *Original = PrimaryCondition
        ? dyn_cast<BinaryOperator>(PrimaryCondition->IgnoreParenImpCasts()) : nullptr;
    if (!Original || Original->getOpcode() != BO_LAnd) return ownedNotFnTraceFalse(__LINE__, __func__);
    for (const auto *Expression : {Original->getLHS(), Original->getRHS()}) {
      const auto *Lookup = dyn_cast<UnresolvedLookupExpr>(Expression->IgnoreParenImpCasts());
      if (!Lookup || Lookup->requiresADL() || Lookup->getNumDecls() != 1 ||
          !Check.family(*Lookup->decls_begin(), {"__type_traits/is_constructible.h"})) return ownedNotFnTraceFalse(__LINE__, __func__);
    }
    // Traverse the actual dependent primary, then each concrete retained role.
    if (!Graph.TraverseType(Factory.PrimaryDefault->getType())) return ownedNotFnTraceFalse(__LINE__, __func__);
    for (const auto *Info : {Factory.SubstitutedDefault, Factory.ConvertedDefault}) {
      if (!constraintType(Info)) return ownedNotFnTraceFalse(__LINE__, __func__);
      const auto Root = specialization(Info);
      const auto *Expression = Root.getArgLoc(0).getArgument().getAsExpr();
      const auto *And = Expression ? dyn_cast<BinaryOperator>(Expression->IgnoreParenImpCasts()) : nullptr;
      const auto *Constructible = And ? dyn_cast<DeclRefExpr>(And->getLHS()->IgnoreParenImpCasts()) : nullptr;
      const auto *Move = And ? dyn_cast<DeclRefExpr>(And->getRHS()->IgnoreParenImpCasts()) : nullptr;
      if (!And || And->getOpcode() != BO_LAnd ||
          !variableUse(Constructible, "is_constructible_v", Callable, Input) ||
          !variableUse(Move, "is_move_constructible_v", Callable, Input)) return ownedNotFnTraceFalse(__LINE__, __func__);
      for (const auto *Reference : {Constructible, Move}) {
        if (!Reference->hasExplicitTemplateArgs() || !Reference->getNumTemplateArgs()) return ownedNotFnTraceFalse(__LINE__, __func__);
        const auto &Argument = Reference->template_arguments()[0];
        if (Argument.getArgument().getKind() != TemplateArgument::Type) return ownedNotFnTraceFalse(__LINE__, __func__);
        const auto Decay = specialization(Argument.getTypeSourceInfo());
        if (!decay(Decay, Input, Callable)) return ownedNotFnTraceFalse(__LINE__, __func__);
      }
    }
    const auto Tags = describeFunctionalNotFnTupleTagSources(S, SM, Factory.Selected, Context);
    if (!Tags || Tags->size() != 4) return ownedNotFnTraceFalse(__LINE__, __func__);
    UtilityTupleQueryGraph Tuple(S, SM, Context, SpecialMembers, OperationTraits,
                                UtilityTupleQueryMode::CatSignature);
    if (!Tuple.bindNotFnTupleTagSlices(Factory.Selected, *Tags, OwnedQuerySources != nullptr)) return ownedNotFnTraceFalse(__LINE__, __func__);
    for (const auto &Tag : *Tags)
      if (!Tuple.TraverseTypeLoc(Tag.Written->getTypeLoc())) return ownedNotFnTraceFalse(__LINE__, __func__);
    // Every selected construction keeps its actual signature. The exact
    // constructor template/default packets must also be present; the pointer
    // layout never supplies their missing source.
    for (const auto *Construction : Factory.Selected.SelectedConstructions) {
      const auto *Constructor = Construction->getConstructor();
      if (Constructor->isInheritingConstructor()) {
        if (Constructor->getParent()->getCanonicalDecl() != Pointer->Record->getCanonicalDecl())
          return ownedNotFnTraceFalse(__LINE__, __func__);
        Constructor = Constructor->getInheritedConstructor().getConstructor();
        if (!Constructor || Constructor->getParent()->getCanonicalDecl() !=
                Pointer->Forwarder->getCanonicalDecl()) return ownedNotFnTraceFalse(__LINE__, __func__);
      }
      const auto *PrimaryTemplate = Constructor->getPrimaryTemplate();
      if (!PrimaryTemplate || !Graph.function(Constructor)) return ownedNotFnTraceFalse(__LINE__, __func__);
      if (const auto *Written = Constructor->getTypeSourceInfo())
        if (!Graph.TraverseNotFnConstructorSignature(Constructor, Written)) return ownedNotFnTraceFalse(__LINE__, __func__);
      bool Found = false;
      for (const auto *Source : Sources) {
        if (!Source || Source->Kind != TemplateSourceKind::Function ||
            Source->Declaration != Constructor) continue;
        bool Selected = false;
        for (const auto *Selection : Selections)
          if (Selection && Selection->FunctionalNotFnConstraint &&
              Selection->Expression == Construction && Selection->Function == Constructor &&
              Selection->Location == Source->Location &&
              matchesFunctionalNotFnSelectedSource(S, SM, *Selection, Context)) Selected = true;
        if (!Selected) continue;
        if (Source->Template != PrimaryTemplate || !arguments(*Source)) return ownedNotFnTraceFalse(__LINE__, __func__);
        for (const auto &Default : Source->Defaults) {
          const auto *Parameter = dyn_cast<TemplateTypeParmDecl>(Default.Parameter);
          if (Parameter) {
            const bool Packet = Parameter->hasDefaultArgument() &&
                Default.Written.getArgument().getKind() == TemplateArgument::Type &&
                Default.Converted.getArgument().getKind() == TemplateArgument::Type;
            const bool Complete = Packet && Graph.TraverseNotFnConstructorDefaultType(Constructor, Parameter);
            std::fprintf(stderr, "OWNED_DEFAULT_PACKET ctor=%p parent=%s primary=%p parameter=%p index=%u hasdefault=%u writtenkind=%u convertedkind=%u packet=%u complete=%u originaltype=%s
",
                static_cast<const void *>(Constructor), Constructor->getParent()->getQualifiedNameAsString().c_str(),
                static_cast<const void *>(PrimaryTemplate), static_cast<const void *>(Parameter), Parameter->getIndex(),
                static_cast<unsigned>(Parameter->hasDefaultArgument()),
                static_cast<unsigned>(Default.Written.getArgument().getKind()),
                static_cast<unsigned>(Default.Converted.getArgument().getKind()), static_cast<unsigned>(Packet),
                static_cast<unsigned>(Complete), Parameter->hasDefaultArgument()
                    ? Parameter->getDefaultArgument().getArgument().getAsType().getAsString().c_str() : "-");
            if (!Complete) return ownedNotFnTraceFalse(__LINE__, __func__);
            const auto *SavedOwner = ConstructorDefaultOwner;
            const auto *SavedSource = ConstructorDefaultSource;
            const auto *SavedSpelling = ConstructorDefaultSpelling;
            auto RestoreConstructor = llvm::make_scope_exit([&] {
              ConstructorDefaultOwner = SavedOwner;
              ConstructorDefaultSource = SavedSource;
              ConstructorDefaultSpelling = SavedSpelling;
            });
            ConstructorDefaultOwner = Constructor;
            ConstructorDefaultSource = Source;
            for (const auto *Spelling : {Default.Written.getTypeSourceInfo(),
                                        Default.Converted.getTypeSourceInfo()}) {
              ConstructorDefaultSpelling = Spelling;
              if (!constraintType(Spelling)) return ownedNotFnTraceFalse(__LINE__, __func__);
            }
          } else if (!Graph.TraverseTemplateArgumentLoc(Default.Written) ||
                     !Graph.TraverseTemplateArgumentLoc(Default.Converted)) return ownedNotFnTraceFalse(__LINE__, __func__);
        }
        if (!parameterTypes(*Source, &Factory)) return ownedNotFnTraceFalse(__LINE__, __func__);
        Found = true;
      }
      if (!Found) return ownedNotFnTraceFalse(__LINE__, __func__);
    }
    return true;
  }
  bool publicInvokeSources(const FunctionalNotFnCallSource &Call) {
    const auto *Operation = Call.OperationCall
        ? dyn_cast_or_null<CXXMethodDecl>(Call.OperationCall->getDirectCallee()) : nullptr;
    const auto *Function = Call.InvokeCall ? Call.InvokeCall->getDirectCallee() : nullptr;
    const auto *Primary = Function ? Function->getPrimaryTemplate() : nullptr;
    const auto *Parameters = Primary ? Primary->getTemplateParameters() : nullptr;
    const auto *First = Parameters && Parameters->size() == 2
        ? dyn_cast<TemplateTypeParmDecl>(Parameters->getParam(0)) : nullptr;
    const auto *Rest = Parameters && Parameters->size() == 2
        ? dyn_cast<TemplateTypeParmDecl>(Parameters->getParam(1)) : nullptr;
    const auto *Arguments = Function ? Function->getTemplateSpecializationArgs() : nullptr;
    if (!Operation || !Function || !Primary || !Arguments || PublicInvokeFunction ||
        !First || !Rest || First->isParameterPack() || !Rest->isParameterPack() ||
        First->getIndex() || Rest->getIndex() != 1 || First->hasDefaultArgument() || Rest->hasDefaultArgument() ||
        Operation->getParent()->getCanonicalDecl() != Call.Storage.Operation->getCanonicalDecl() ||
        !Check.family(Operation, {"__functional/not_fn.h"}) ||
        !Check.family(Function, {"__functional/invoke.h"}) ||
        !Check.family(Primary, {"__functional/invoke.h"}) ||
        !Check.family(First, {"__functional/invoke.h"}) || !Check.family(Rest, {"__functional/invoke.h"}) ||
        isa<CXXMethodDecl>(Function) || Function->isDeleted() || Function->isInvalidDecl() ||
        Function->isVariadic() || Function->getTemplateSpecializationKind() != TSK_ImplicitInstantiation ||
        Function->getNumParams() != Operation->getNumParams() || !Operation->getNumParams() ||
        Operation->getNumParams() > 64 || Arguments->size() != 2 ||
        Arguments->get(0).getKind() != TemplateArgument::Type ||
        Arguments->get(1).getKind() != TemplateArgument::Pack ||
        Arguments->get(1).pack_size() + 1 != Operation->getNumParams()) return ownedNotFnTraceFalse(__LINE__, __func__);
    for (const auto *Redeclaration : Function->redecls())
      if (!Check.family(Redeclaration, {"__functional/invoke.h"})) return ownedNotFnTraceFalse(__LINE__, __func__);
    const auto Pack = Arguments->get(1).pack_elements();
    for (unsigned I = 0; I < Function->getNumParams(); ++I) {
      const auto Input = Operation->getParamDecl(I)->getType();
      if (!Input->isReferenceType() || Function->getParamDecl(I)->hasDefaultArg() ||
          !Context.hasSameType(Function->getParamDecl(I)->getType(), Input)) return ownedNotFnTraceFalse(__LINE__, __func__);
      // Both SDK calls forward the same parameter. Deduction keeps an
      // lvalue reference but removes the reference from an xvalue; the
      // independently checked function parameter still has Input's exact
      // reference and const qualification. Apply this to the callable too.
      const auto &Deduced = I ? Pack[I - 1] : Arguments->get(0);
      if (Deduced.getKind() != TemplateArgument::Type ||
          !Context.hasSameType(Deduced.getAsType(), Input->isLValueReferenceType()
              ? Input : Input->getPointeeType())) return ownedNotFnTraceFalse(__LINE__, __func__);
    }
    std::vector<const CallExpr *> Roots, Forwards;
    for (const auto Mode : {FunctionalNotFnSourceMode::Signature,
                           FunctionalNotFnSourceMode::Exception, FunctionalNotFnSourceMode::Runtime}) {
      const auto Source = describeFunctionalNotFnCallSource(S, SM, Call.SourceCall, Context, Mode);
      const auto *Negation = Source ? dyn_cast_or_null<UnaryOperator>(Source->Negation) : nullptr;
      if (!Source || Source->OperationCall->getDirectCallee() != Operation ||
          (Negation ? Negation->getOpcode() != UO_LNot
                    : !approvedFunctionalNotFnPointerNegation(S, SM, *Source, Context))) return ownedNotFnTraceFalse(__LINE__, __func__);
      const auto *Root = Source->InvokeCall;
      const auto *Reference = Root ? dyn_cast<DeclRefExpr>(Root->getCallee()->IgnoreParenImpCasts()) : nullptr;
      if (!Root || !Reference || Reference->getDecl() != Function || Root->getDirectCallee() != Function ||
          Root->isTypeDependent() || Root->isValueDependent() || Root->getNumArgs() != Operation->getNumParams() ||
          !Check.location(Reference->getExprLoc(), {"__functional/not_fn.h"}) ||
          !Context.hasSameType(Root->getType(), Function->getReturnType().getNonLValueExprType(Context)) ||
          Root->getValueKind() != Expr::getValueKindForType(Function->getReturnType())) return ownedNotFnTraceFalse(__LINE__, __func__);
      bool Selected = false, Retained = false;
      for (const auto *Selection : Selections)
        if (Selection && Selection->Expression == Root && Selection->Function == Function) {
          if (!Selection->FunctionalNotFnConstraint || Selection->Location != Reference->getExprLoc() ||
              !matchesFunctionalNotFnSelectedSource(S, SM, *Selection, Context)) return ownedNotFnTraceFalse(__LINE__, __func__);
          Selected = true;
        }
      for (const auto *Source : Sources) {
        if (!Source || Source->Declaration != Function || Source->Location != Reference->getExprLoc()) continue;
        if (Source->Kind != TemplateSourceKind::Function || Source->Template != Primary ||
            !Source->FunctionalNotFnConstraint || !arguments(*Source) || Source->Type || Source->Underlying ||
            Source->Written || Source->Instantiation || Source->Origin || Source->WrittenStorageClass ||
            Source->Selection || !Source->Defaults.empty() || !Source->ParameterTypes.empty() ||
            Source->Canonical->size() != Arguments->size()) return ownedNotFnTraceFalse(__LINE__, __func__);
        for (unsigned I = 0; I < Arguments->size(); ++I)
          if (!Source->Canonical->get(I).structurallyEquals(Arguments->get(I))) return ownedNotFnTraceFalse(__LINE__, __func__);
        Retained = true;
      }
      if (!Selected || !Retained) return ownedNotFnTraceFalse(__LINE__, __func__);
      for (unsigned I = 0; I < Root->getNumArgs(); ++I) {
        const CallExpr *Forward = nullptr;
        if (!Check.forwarding(Root->getArg(I), Operation->getParamDecl(I),
                              "__functional/not_fn.h", Forward)) return ownedNotFnTraceFalse(__LINE__, __func__);
        Forwards.push_back(Forward);
      }
      Roots.push_back(Root);
    }
    if (!Graph.bindNotFnPublicInvoke(Function, Operation, Roots, Forwards)) return ownedNotFnTraceFalse(__LINE__, __func__);
    PublicInvokeFunction = Function;
    const auto *Pattern = Primary->getTemplatedDecl();
    const auto *Info = Function->getTypeSourceInfo();
    if (!Pattern || !Info || !Pattern->getTypeSourceInfo() ||
        !Graph.TraverseTypeLoc(Info->getTypeLoc()) || !Graph.function(Function) ||
        !Graph.TraverseTypeLoc(Pattern->getTypeSourceInfo()->getTypeLoc())) return ownedNotFnTraceFalse(__LINE__, __func__);
    // Metadata signatures are complete; the original runtime helper bodies,
    // forwarding, negation and lifetime proofs remain independent obligations.
    return true;
  }
  bool callDefaults(const FunctionalNotFnCallSource &Call, const TemplateUseSource &Use,
      std::set<const CXXMethodDecl *> *OwnedQuerySources = nullptr) {
    if (PublicInvokeFunction || PublicNothrowInitializer) return ownedNotFnTraceFalse(__LINE__, __func__);
    auto RestorePublicInvoke = llvm::make_scope_exit([&] {
      PublicInvokeFunction = nullptr;
      PublicNothrowInitializer = false;
    });
    if (!Graph.bindNotFnOperation(Call.Storage, OwnedQuerySources) ||
        !Graph.bindNotFnConstraintVariables([this, Call](const DeclRefExpr *Reference) {
          return invocationVariableUse(Reference, Call);
        })) return ownedNotFnTraceFalse(__LINE__, __func__);
    const auto *Method = Call.Method;
    const auto *Primary = Method ? Method->getPrimaryTemplate() : nullptr;
    const auto *Arguments = Method ? Method->getTemplateSpecializationArgs() : nullptr;
    const auto *SourceCall = Call.SourceCall;
    const auto *Reference = SourceCall
        ? dyn_cast<DeclRefExpr>(SourceCall->getCallee()->IgnoreParenImpCasts()) : nullptr;
    if (!SourceCall || !Reference || Reference->getDecl() != Method ||
        SourceCall->getOperator() != OO_Call ||
        SourceCall->getDirectCallee() != Method || !SourceCall->getNumArgs() ||
        SourceCall->getArg(0)->IgnoreParens() != Call.Receiver ||
        !S.owns(SM, Reference->getExprLoc()) || !Use.Location.isValid()) return ownedNotFnTraceFalse(__LINE__, __func__);
    bool Selected = false;
    // Retain the original owned-source proof. Only an SDK-origin packet
    // needs the additional exact retained selection of this same method.
    bool DefaultOccurrence = S.owns(SM, Use.Location);
    for (const auto *Selection : Selections) {
      if (!Selection || !Selection->FunctionalNotFnConstraint ||
          Selection->Function != Method ||
          !matchesFunctionalNotFnSelectedSource(S, SM, *Selection, Context)) continue;
      if (Selection->Expression == SourceCall &&
          Selection->Location == Reference->getExprLoc()) Selected = true;
      // A packet retains its own deduction occurrence. SDK signature queries
      // can retain another occurrence of this same specialization; both that
      // event and the independent owned call must be authenticated. This
      // metadata binding grants no SDK runtime body or lifetime permission.
      if (Selection->Location == Use.Location) DefaultOccurrence = true;
    }
    // Deduction/default packets belong to this exact instantiated method and
    // canonical/sugared arguments below. Repeated uses retain their own call
    // selections; their source location need not equal the first deduction.
    if (!Selected || !DefaultOccurrence || !Primary || !Arguments ||
        Use.Template != Primary || Use.Declaration != Method ||
        Use.Kind != TemplateSourceKind::Function || !Use.FunctionalNotFnConstraint ||
        !arguments(Use) || Use.Defaults.size() != 1 ||
        Use.Canonical->size() != Arguments->size()) return ownedNotFnTraceFalse(__LINE__, __func__);
    for (unsigned I = 0; I < Arguments->size(); ++I)
      if (!Use.Canonical->get(I).structurallyEquals(Arguments->get(I))) return ownedNotFnTraceFalse(__LINE__, __func__);
    return Graph.withNotFnInvocation(Call, [&] {
    if (!Graph.prepareNotFnInvokeSignatures(Sources, Selections) ||
        !Graph.prepareNotFnTryResultSignatures(Sources, Selections)) return ownedNotFnTraceFalse(__LINE__, __func__);
    // Close the concrete inner invoke result before the outer operator's
    // constraint reaches it. Use this SAME graph and its original cumulative
    // node/depth limits; only a fully successful dependency may be cached.
    // All original primary, Written and Converted roles still traverse below.
    const auto *Invoke = Call.InvokeCall;
    const auto *Callee = Invoke ? Invoke->getDirectCallee() : nullptr;
    const auto *Info = Callee ? Callee->getTypeSourceInfo() : nullptr;
    const auto Prototype = Info ? Info->getTypeLoc().getAs<FunctionProtoTypeLoc>()
                                : FunctionProtoTypeLoc();
    const auto Return = Prototype ? Prototype.getReturnLoc() : TypeLoc();
    const auto *Result = Return ? specialization(Return.getType()) : nullptr;
    const auto *Alias = Result ? dyn_cast_or_null<TypeAliasTemplateDecl>(
        Result->getTemplateName().getAsTemplateDecl()) : nullptr;
    if (!Invoke || !Callee || !Callee->getIdentifier() || Callee->getName() != "invoke" ||
        !Callee->getPrimaryTemplate() || !Check.family(Callee, {"__functional/invoke.h"}) ||
        !Check.location(Invoke->getExprLoc(), {"__functional/not_fn.h"}) ||
        Invoke->getNumArgs() != Callee->getNumParams() ||
        !Alias || Alias->getName() != "invoke_result_t" ||
        !Check.family(Alias, {"__type_traits/invoke.h"}) ||
        !Context.hasSameType(Return.getType(), Callee->getReturnType()) ||
        !Graph.TraverseTypeLoc(Return) || !publicInvokeSources(Call)) return ownedNotFnTraceFalse(__LINE__, __func__);
    // Close this selected dependency at the original graph root, after its
    // public operation is authenticated and before the independent defaults.
    if (!Graph.prepareNotFnOperationInvokeSignatures(Sources, Selections)) return ownedNotFnTraceFalse(__LINE__, __func__);
    // The outer invocability probe is a separate real selected member call.
    // Close its original primary, result alias and ellipsis witness at this
    // same root, after the precise operation invoke dependency is complete.
    if (!Graph.prepareNotFnTryResultSignatures(Sources, Selections, true)) return ownedNotFnTraceFalse(__LINE__, __func__);
    const auto &Default = Use.Defaults.front();
    const auto *Parameter = dyn_cast<TemplateTypeParmDecl>(Default.Parameter);
    if (!Parameter || !Parameter->hasDefaultArgument() ||
        Default.Written.getArgument().getKind() != TemplateArgument::Type ||
        Default.Converted.getArgument().getKind() != TemplateArgument::Type ||
        !Graph.TraverseType(Parameter->getDefaultArgument().getArgument().getAsType()) ||
        !constraintType(Default.Written.getTypeSourceInfo()) ||
        !constraintType(Default.Converted.getTypeSourceInfo()) ||
        !parameterTypes(Use)) return ownedNotFnTraceFalse(__LINE__, __func__);
    return true;
    });
  }
};

bool retainNeverCOperationTraitSource(
    ASTContext &Context, unsigned Count, const SourceLocation &Location) override {
  static unsigned OwnedTraitRequests = 0;
  if (OwnedTraitRequests++ < 16384) {
    const auto &SM = Context.getSourceManager();
    const auto Origin = S.sdkFile(SM, Location);
    const auto P = SM.getPresumedLoc(Location);
    std::fprintf(stderr, "OWNED_TRAIT_RETENTION count=%u rawloc=%u owned=%u root=%s path=%s line=%u column=%u diagnostics=%zu\n",
        Count, Location.getRawEncoding(), static_cast<unsigned>(S.owns(SM, Location)),
        Origin ? Origin->Root.c_str() : "-", Origin ? Origin->Path.c_str() : "-",
        P.isValid() ? P.getLine() : 0, P.isValid() ? P.getColumn() : 0, S.Diagnostics.size());
  }

  bool DestructionLookupAttempted, bool DestructionExceptionAttempted) override {
static unsigned OwnedTraitEvents = 0;
if (OwnedTraitEvents++ < 16384 && Query && Query->getNumArgs() == 2)
  std::fprintf(stderr, "OWNED_TRAIT_EVENT ptr=%p trait=%u args=%u rawloc=%u target=%s input=%s operands=%u attempted=%u complete=%u rootkind=%s\n",
      static_cast<const void *>(Query), static_cast<unsigned>(Query->getTrait()), Query->getNumArgs(),
      Query->getExprLoc().getRawEncoding(), Query->getArg(0)->getType().getAsString().c_str(),
      Query->getArg(1)->getType().getAsString().c_str(), Count, static_cast<unsigned>(Attempted),
      static_cast<unsigned>(Complete), Root ? Root->getStmtClassName() : "-");

std::fprintf(stderr, "OWNED_NOT_FN_CALL line=%u owned=%u signature=%u exception=%u negation=%u source=%u\n",
    A.Sources.getPresumedLineNumber(Call->getExprLoc()), static_cast<unsigned>(bool(Owned)),
    static_cast<unsigned>(bool(Signature)), static_cast<unsigned>(bool(Exception)),
    static_cast<unsigned>(NegationSource), static_cast<unsigned>(Source));
// Consume the selected operator's real enable_if/default packet, including

std::fprintf(stderr, "OWNED_NOT_FN_DEFAULT line=%u selected=%u source=%u\n",
    A.Sources.getPresumedLineNumber(Call->getExprLoc()),
    static_cast<unsigned>(SelectedDefault), static_cast<unsigned>(Source));
if (!SelectedDefault) { Source = false; break; }
